/**
 * Brightness standing of a magnitude: pct = share of 1800-2300 epochs
 * when the body was FAINTER than this (0 = faintest ever, 100 =
 * brightest ever); z = sigmas brighter than the mean (positive =
 * brighter than average).
 * @param {number} bodyId 0..9
 * @param {number} mag apparent magnitude
 * @returns {{pct: number, z: number}}
 */
export function magBrightness(bodyId, mag) {
  const st = MAG_STATS[bodyId];
  if (!st || !Number.isFinite(mag)) return { pct: NaN, z: NaN };
  const q = st.q;
  let pct;
  if (mag <= q[0]) pct = 100;
  else if (mag >= q[100]) pct = 0;
  else {
    let lo = 0, hi = 100;
    while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (q[mid] <= mag) lo = mid; else hi = mid; }
    const span = q[hi] - q[lo] || 1;
    pct = 100 - (lo + (mag - q[lo]) / span);
  }
  return { pct, z: (st.mean - mag) / st.std };
}
